insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 1, '¡Ah, Señor! ¿Cómo es que se han aumentado tanto mis perseguidores? Son muchísimos los que se han rebelado contra mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 2, 'Muchos dicen de mí: Ya no tiene que esperar de su Dios salvación o amparo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 3, 'Pero tú, ¡oh Señor!, tú eres mi protector, mi gloria, y el que me haces levantar cabeza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 4, 'A voces clamé al Señor, y él me oyó benigno desde su santo monte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 5, 'Yo me dormí, y me entregué a un profundo sueño; y me levanté, porque el Señor me tomó bajo su amparo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 6, 'No temeré, pues, a ese innumerable gentío que me tiene cercado; levántate, ¡oh Señor!, sálvame tú, Dios mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 7, 'Pues tú has castigado a todos los que sin razón me hacen guerra');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 3, 8, 'Del Señor nos viene la salvación; y tú, oh Dios mío, bendecirás a tu pueblo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 1, 'Presta oídos, Señor, a mis palabras; escucha mis clamores.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 2, 'Atiende a la voz de mis súplicas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 3, 'Porque a ti enderezaré mi oración; de mañana, ¡oh Señor!, oirás mi voz.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 4, 'Al amanecer me pondré en tu presencia, y te contemplaré. Porque no eres tú un Dios que ame la iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 5, 'Ni morará junto a ti el maligno, ni los injustos podrán permanecer delante de tus ojos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 6, 'Tú aborreces a todos los que obran la iniquidad; tú perderás a todos aquellos que hablan mentira. Al hombre sanguinario y fraudulento, el Señor lo abominará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 7, 'Pero yo confiado en tu gran misericordia, entraré en tu casa; y poseído de tu santo temor, doblaré mis rodillas ante tu santo templo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 8, 'Guíame, ¡oh Señor!, por la senda de tu injusticia; haz que sea recto ante tus ojos mi camino, por causa de mis enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 9, 'Pues en su boca no se halla palabra de verdad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 10, 'Su garganta es un sepulcro abierto; con sus lenguas urden continuamente engaños. Júzgalos, ¡oh Dios mío. Frústrense sus designios, arrójalos fuera, lejos de tu presencia, como lo merecen sus muchas impiedades; puesto que, ¡oh Señor!, te han irritado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 11, 'Al contrario, alégranse todos aquellos que ponen en ti su esperanza: Se regocijarán eternamente, y tú morarás en ellos. Y en ti se glorificarán todos los que aman tu santo Nombre,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 5, 12, 'porque tú colmarás de bendiciones al justo. Señor, con tu benevolencia, como con un escudo, nos has cubierto por todos lados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 1, 'Señor, no me reprendas en medio de tu saña, ni me castigues en la fuerza de tu enojo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 2, 'Ten, Señor, misericordia de mí, que estoy sin fuerzas; sáname, oh Señor, porque hasta mis huesos se han estremecido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 3, 'Y está mi alma sumamente perturbada: pero tú, Señor, ¿hasta cuándo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 4, 'Vuélvete a mí, Señor, y libra mi alma; sálvame por tu misericordia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 5, 'Porque muriendo ya no hay quien se acuerde de ti; y en el infierno, ¿quién te tributará alabanzas?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 6, 'Me he consumido a fuerza de tanto gemir');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 7, 'Por causa de la indignación se han oscurecido mis ojos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 8, 'Apartaos lejos de mí todos los que obráis la iniquidad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 9, 'Ha otorgado el Señor mi súplica');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 6, 10, 'Avergüéncense, y queden llenos de la mayor turbación todos mis enemigos; retírense, y váyanse al momento cubiertos de ignominia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 1, 'Señor, Dios mío, en ti he puesto mi esperanza; sálvame de todos mis perseguidores, y líbrame.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 2, 'No sea que alguno, como león, arrebate tal vez mi alma, sin que haya nadie que me libre y ponga a salvo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 3, '¡Ah Señor Dios mío! si yo tal hice, si hay iniquidad en mis acciones,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 4, 'si he vuelto mal por mal a los que me lo han hecho, caiga yo justamente en las garras de mis enemigos, sin recurso.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 5, 'Persígame el enemigo, y apodérese de mí, y estrélleme contra el suelo, y reduzca a polvo mi gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 6, 'Levántate, ¡oh Señor! en el momento de tu enojo, y ostenta tu grandeza en medio de mis enemigos. Sí, Señor Dios mío, levántate según la ley por ti establecida;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 7, 'y el concurso de las naciones se reunirá alrededor de ti. Por amor de esta congregación vuelve a subir a lo alto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 8, 'El Señor es quien juzga a los pueblos. Júzgame, pues, oh Señor, según mi justicia, y según la inocencia que hay en mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 9, 'Acábese ya la malicia de los pecadores; y tú, ¡oh Dios!, que penetras los corazones, y los afectos más íntimos, encaminarás al justo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 10, 'Mi socorro lo espero del Señor');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 11, 'Dios, justo juez, fuerte y misericordioso, ¿se enoja acaso todos los días?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 12, 'Si vosotros no os convirtiereis vibrará su espada');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 13, 'y en él ha puesto dardos mortales, y tiene dispuestas sus abrasadoras saetas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 14, 'He aquí que el impío ha parido la injusticia; concibió el dolor, y parió el pecado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 15, 'El abrió y ahondó una fosa');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 16, 'El dolor que quiso ocasionarme, recaerá contra él; y su iniquidad descargará sobre su cabeza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 7, 17, 'Glorificaré yo al Señor por su justicia y cantaré himnos de alabanza al excelso Nombre del Señor altísimo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 1, 'Oh Señor, soberano dueño nuestro, ¡cuán admirable es tu santo Nombre en toda la tierra! Porque tu majestad se ve ensalzada sobre los cielos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 2, 'De la boca de los niños y de los que están aún pendientes del pecho de sus madres, hiciste tú salir perfecta alabanza, por razón de tus enemigos, para destruir al enemigo y al vengativo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 3, 'Yo contemplo tus cielos, obra de tus dedos, la luna y las estrellas que tú creaste, y exclamo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 4, '¿Qué es el hombre, para que tú te acuerdes de él? ¿O que es el hijo del hombre, para que vengas a visitarlo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 5, 'Lo hiciste un poco inferior a los ángeles, lo coronaste de gloria y de honor,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 6, 'y le has dado el mando sobre las obras de tus manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 7, 'Todas ellas las pusiste a sus pies; todas las ovejas y bueyes, y aun las bestias del campo;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 8, 'las aves del cielo, y los peces del mar que hienden sus ondas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 8, 9, '¡Oh Señor, soberano dueño nuestro, ¡y cuán admirable es tu Nombre en toda la redondez de la tierra!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 1, 'A ti, ¡oh Señor!, tributaré gracias con todo mi corazón; contaré todas tus maravillas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 2, 'Me alegraré en ti y saltaré de gozo; cantaré himnos a tu Nombre, ¡oh Dios altísimo!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 3, 'Porque tú pusiste en fuga a mis enemigos; y quedarán debilitados, y perecerán delante de ti.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 4, 'Pues tú me has hecho justicia, y has tomado la defensa de mi causa; te has sentado sobre el trono, tú que juzgas según justicia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 5, 'Has reprendido a las naciones, y pereció el impío; has borrado sus nombres para siempre por los siglos de los siglos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 6, 'Quedan embotadas para siempre las espadas del enemigo, y has asolado sus ciudades. Se desvaneció como el sonido su memoria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 7, 'Mas el Señor subsiste eternamente. El preparó su trono para ejercer el juicio');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 8, 'y él mismo es quien juzgará con rectitud la tierra');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 9, 'El Señor se ha hecho el amparo del pobre');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 10, 'Confíen, pues, en ti, ¡oh Dios mío!, los que conocen y adoran tu Nombre; porque jamás has desamparado, Señor, a los que a ti recurren.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 11, 'Cantad himnos al Señor que tiene su morada en el monte santo de Sión');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 12, 'Porque vengando la sangre de sus siervos, ha hecho ver que se acuerda de ellos; no ha echado en olvido el clamor de los pobres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 13, 'Apiádate, Señor, de mí; mira el abatimiento a que me han reducido mis enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 14, 'Tú que me sacas de las puertas de la muerte, para que publique todas tus alabanzas en las puertas de la hija de Sión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 15, 'Manifestaré mi júbilo por haberme tú salvado; las gentes que me perseguían han quedado sumidas en la perdición que habían preparado contra mí. En el lazo mismo, que me tenían ocultamente armado, ha quedado preso su pie.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 16, 'Así se reconocerá que el Señor hace justicia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 17, 'Serán arrojados al infierno los pecadores, y todas esas gentes que viven olvidadas de Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 18, 'Que no estará para siempre olvidado el pobre');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 19, 'Levántate, ¡oh Señor!, haz que no prevalezca el hombre malvado; sean juzgadas las gentes ante tu presencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 20, 'Establece, Señor, sobre ellas un legislador; para que conozcan que son hombres débiles y miserables.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 21, '¿Y por qué, ¡oh Señor!, te has retirado a lo lejos, y me has desamparado en el tiempo más crítico, en la tribulación?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 22, 'Mientras que el impío se llena de soberbia, se requema el pobre; mas en fin, los impíos son cogidos en los mismos designios o tramas que han urdido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 23, 'Por cuanto el pecador se jacta en los perversos deseos de su alma');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 24, 'Por lo mismo, orgulloso el pecador ha exasperado al Señor, y no le buscará según el exceso de su arrogancia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 25, 'Delante de él no hay Dios; y así sus procederes son siempre viciosos. Tus juicios, Señor, los ha apartado lejos de su vista, sólo piensa en dominar a todos sus enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 26, 'Pues él ha dicho en su corazón: Nunca jamás seré yo derrocado');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 27, 'Está su boca llena de maldición y de amargura, y de dolor; debajo de su lengua opresión y dolor para el prójimo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 28, 'Se pone al acecho con los ricos en sitios escondidos, para matar al inocente;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 29, 'tiene siempre su vista fija contra el pobre; está acechando desde la emboscada, como un león desde su cueva. Acecha para echar sus garras sobre el pobre, para agarrar al pobre, atrayéndole dolosamente hacia sí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 30, 'Lo hará caer en su lazo; se agachará en tierra, y se echará encima de los pobres, luego que los haya apresado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 31, 'Porque él dijo en su corazón: Dios ya de nada se acuerda');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 32, 'Levántate, pues, ¡oh Señor Dios!, alza tu poderosa mano; no te olvides de los pobres o desvalidos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 33, '¿Por qué razón el impío ha irritado así a Dios? Es porque ha dicho en su corazón: Dios de nada se cuida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 34, 'Pero tú, Señor, lo estás viendo; tú consideras el afán y el dolor del oprimido; para entregar a los malvados al castigo de tus manos. A cargo tuyo está la tutela del pobre; tú eres el amparo del huérfano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 35, 'Quebranta el brazo del pecador y del maligno; y entonces se buscará el fruto de su pecado, y no se hallará nada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 36, 'Reinará el Señor eternamente y por los siglos de los siglos; vosotros, ¡oh naciones impías!, seréis extirpadas de su tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 37, 'Atendiste, ¡oh Señor!, al deseo de los pobres; prestaste benignos oídos a la rectitud de su corazón,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 9, 38, 'para hacer justicia al huérfano y al oprimido');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 1, 'En el Señor tengo puesta mi confianza: ¿Cómo, pues, decís a mi alma: Retírate prontamente al monte, como un ave que huye?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 2, 'Mira que los pecadores han apuntado el arco, y tienen preparadas saetas dentro de sus aljabas, para asaetar a escondidas a los que son de corazón recto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 3, 'Porque aquello que tú hiciste de bueno, lo han reducido a nada; mas el justo, ¿qué es lo que ha hecho de malo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 4, 'Pero el Señor está en su santo templo, el Señor tiene su trono en el cielo. Sus ojos están mirando al pobre; sus párpados están examinando a los hijos de los hombres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 5, 'El Señor vigila al justo y al impío; y así el que ama la maldad, odia su propia alma.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 6, 'Lloverá lazos o desastres sobre los pecadores; el fuego, y azufre, y el viento tempestuoso son el cáliz, o bebida, que les tocará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 10, 7, 'Porque el Señor es justo y ama la justicia, está siempre su rostro mirando la rectitud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 1, 'Sálvame, Señor; porque ya no se halla un hombre de bien sobre la tierra; porque las verdades no se aprecian ya entre los hijos de los hombres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 2, 'Cada uno de ellos no habla sino con mentira a su prójimo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 3, 'Acabe el Señor con todo labio tramposo y con la lengua jactanciosa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 4, 'Ellos han dicho: Nosotros con nuestra lengua, o artificiosas palabras, haremos cosas grandes; somos dueños de nuestros labios; ¿quién nos manda a nosotros?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 5, 'Pero el Señor mirando a la miseria de los desvalidos, y al gemido de los pobres, dice: Ahora me levantaré yo para defenderlos. Los pondré a salvo; yo les inspiraré confianza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 6, 'Palabras puras y sinceras son las palabras del Señor; son plata ensayada al fuego, acendrada en el crisol, y siete o mil veces refinada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 7, '¡Oh Señor!, tú nos salvarás, y nos defenderás siempre de esta raza de gentes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 11, 8, 'Los impíos andan alrededor de nosotros: Tú, según tu grandeza o altísima sabiduría, has multiplicado los hijos de los hombres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 1, 'Los cielos publican la gloria de Dios y el firmamento anuncia la grandeza de las obras de sus manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 2, 'Cada día transmite con abundancia al siguiente día estas voces o anuncios, y una noche las comunica a la otra noche.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 3, 'No hay lenguaje, ni idioma, en los cuales no sean escuchadas sus voces.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 4, 'Su sonido se ha propagado por toda la tierra, y hasta el cabo del mundo se han oído sus palabras.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 5, 'Puso Dios especialmente en el Sol su Tabernáculo; y a manera de un esposo que sale de su tálamo, salta como gigante a correr su carrera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 6, 'Sale de una extremidad del cielo, y corre hasta la otra; no hay quién pueda esconderse de su calor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 7, 'La ley del Señor es inmaculada, y ella convierte a sí las almas; el testimonio del Señor es fiel, y da sabiduría a los pequeños.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 8, 'Los mandamientos del Señor son rectos, y alegran los corazones; el luminoso precepto del Señor es el que alumbra los ojos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 9, 'El puro y santo temor del Señor permanece por todos los siglos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 10, 'Son más codiciables que la abundancia de oro y de piedras preciosas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 11, 'Por eso tu siervo los guarda');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 12, '¿Quién es el que conoce todos sus yerros? Purifícame de los míos ocultos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 13, 'y perdona a tu siervo los ajenos. Si no dominaren sobre mí, entonces estaría limpio de toda mancha y purificado de delito muy grande.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 18, 14, 'Con lo que te serán gratas las palabras o cánticos de mi boca, como también la meditación de mi corazón que haré yo siempre en tu acatamiento. ¡Oh Señor, amparo mío y redentor mío!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 1, 'Que te oiga, ¡oh rey!, el Señor el día de la tribulación; que te defienda el Nombre del Dios de Jacob.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 2, 'Que te envíe socorro desde el santuario, y sea tu firme apoyo desde Sión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 3, 'Tenga presente todos tus sacrificios, y le sea gratísimo tu holocausto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 4, 'Que te conceda lo que desea tu corazón, y cumpla todos sus designios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 5, 'Nosotros nos alegraremos por tu salud y nos gloriaremos en el Nombre de nuestro Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 6, 'Otorgue el Señor todas tus peticiones. Ahora veo que el Señor ha puesto a salvo a su ungido. El le oirá desde el cielo, que es su santuario, en su poderosa diestra está la salvación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 7, 'Unos confían en sus carros armados, otros en sus caballos; mas nosotros invocaremos el Nombre del Señor nuestro Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 8, 'Ellos se hallaron envueltos en los lazos y cayeron; pero nosotros realzamos, y estamos llenos de vigor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 19, 9, '¡Oh Señor!, salva al rey, y óyenos el día en que te invocaremos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 1, 'Oh, Señor, en tu gran poder hallará el rey su alegría, y saltará de extremado gozo por la salvación que le has enviado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 2, 'Tú le has cumplido el deseo de su corazón, y no has frustrado los ruegos que formaron sus labios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 3, 'Antes te has anticipado a él con bendiciones amorosas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 4, 'Te pidió vida, y tú le has concedido alargar sus días por los siglos de los siglos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 5, 'Grande es su gloria por la salvación que le has dado. Aún le revistarás de una gloria y esplendor mucho más grande.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 6, 'Porque tú harás que él sea bendición eterna');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 7, 'Por cuanto el rey tiene puesta su confianza en el Señor');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 8, 'Alcance tu poderosa mano a todos tus enemigos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 9, 'Mostrándoles tu rostro, harás de ellos como un horno encendido. Airado el Señor los pondrá en consternación, y el fuego los devorará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 10, 'Extirparás su descendencia de la faz de la tierra, y quitarás su raza de entre los hijos de los hombres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 11, 'Porque urdieron contra ti maldades');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 12, 'Tú los pondrás en fuga, y tendrás aparejadas contra ellos, las flechas de tu arco.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 20, 13, 'Ensálzate, Señor, con tu poder infinito; que nosotros celebraremos con cánticos e himnos tus maravillas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 1, '¡Oh Dios!, ¡oh Dios mío, vuelve a mí tus ojos! ¿Por qué me has desamparado? Los gritos de los pecados míos alejan de mí la salud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 2, 'Clamaré, oh Dios mío, durante el día, y no me oirás; clamaré de noche, y no por mi culpa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 3, 'Tú habitas en la santa morada, tú, ¡oh gloria de Israel!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 4, 'En ti esperaron nuestros padres; esperaron en ti, y tú los libraste.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 5, 'A ti clamaron, y fueron puestos a salvo. Confiaron en ti, y no tuvieron por qué avergonzarse.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 6, 'Bien que yo soy un gusano, y no un hombre; el oprobio de los hombres, y el desecho de la gente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 7, 'Todos los que me miran, hacen mofa de mí con palabras y con meneos de cabeza, diciendo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 8, 'En el Señor esperaba que le liberte; sálvele, ya que tanto le ama.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 9, 'Sin embargo, tú eres quien me sacó del seno materno; y mi esperanza desde que yo estaba colgado de los pechos de mi madre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 10, 'Desde las entrañas de mi madre fui arrojado en tus brazos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 11, 'No te apartes de mí; porque se acerca la tribulación, y no hay nadie que me socorra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 12, 'Cercado me han novillos en gran número');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 13, 'Abrieron su boca contra mí, como león rapante y rugiente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 14, 'Me he disuelto como agua, y todos mis huesos se han dispersado. Mi corazón está como una cera, derritiéndose dentro de mis entrañas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 15, 'Todo mi verdor se ha secado, como un vaso de barro cocido; mi lengua se ha pegado al paladar; y me vas conduciendo al polvo del sepulcro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 16, 'Porque me veo cercado de una multitud de rabiosos perros: me tiene sitiado una turba de malignos. Han taladrado mis manos y mis pies.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 17, 'Han contado mis huesos uno por uno. Se pusieron a mirarme despacio, y a observarme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 18, 'Repartieron entre sí mis vestidos y sortearon mi túnica.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 19, 'Mas tú, oh Señor, no me dilates tu socorro; atiende luego a mi defensa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 20, 'Libra mi vida, oh Dios, de la espada; y de las garras de los canes de mi alma.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 21, 'Sálvame de la boca del león');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 22, 'Anunciaré tu santo Nombre a mis hermanos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 23, 'Oh, vosotros que teméis al Señor, alabadle; glorificadle vosotros, descendientes todos de Jacob.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 24, 'Témale todo el linaje de Israel, porque no despreció ni desatendió la súplica del pobre, ni apartó de mí su rostro; antes así que clamé a él, luego me oyó.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 25, 'A ti se dirigirán mis alabanzas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 26, 'Los pobres comerán y quedarán saciados');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 27, 'Se acordará de los beneficios recibidos, y se convertirá al Señor toda la extensión de la tierra; y se postrarán ante su acatamiento las familias todas de las gentes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 28, 'Porque del Señor es el reino');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 29, 'Comieron, y le adoraron todos los ricos de la tierra; ante su acatamiento se postrarán todos los mortales.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 30, 'Y mi alma vivirá para él, y a él servirá mi descendencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 21, 31, 'Será contada como la del Señor la generación venidera; y los cielos anunciarán la justicia de él al pueblo que nacerá, formado por el Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 1, 'Te glorificaré, ¡oh Señor!, por haberte declarado protector mío, no dejando que mis enemigos se gozaran a costa de mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 2, '¡Oh Señor Dios mío!, yo clamé a ti, y me diste la salud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 3, 'Tú sacaste, Señor, mi alma del infierno o sepulcro. Tú me salvaste, para que no cayera con los que descienden al profundo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 4, '¡Oh vosotros santos del Señor!, cantadle himnos, y celebrad su memoria sacrosanta.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 5, 'Porque de su indignación procede el castigo; y de su buena voluntad pende la vida. Hasta la tarde durará el llanto, y al salir la aurora será la alegría.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 6, 'En medio de mi prosperidad había yo dicho. No experimentaré nunca jamás mudanza alguna.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 7, '¡Oh Señor!, tu buena voluntad es la que ha dado consistencia a mi floreciente estado. Apartaste de mí tu rostro, y al instante fui trastornado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 8, 'A ti, ¡oh Señor!, clamaré, y a ti, Dios mío, dirigiré mis plegarias.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 9, '¿Qué utilidad te acarreará mi muerte, y al descender yo a la corrupción del sepulcro? ¿Acaso el polvo cantará tus alabanzas, o anunciará tus verdades?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 10, 'Me oyó el Señor, y se apiadó de mí. Se declaró el Señor protector mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 11, 'Trocaste, ¡oh Dios!, mi llanto en regocijo, rasgaste mi cilicio, y me revestiste de gozo,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 29, 12, 'a fin de que sea mi gloria el cantar tus alabanzas, y nunca tenga yo penas. ¡Oh Señor Dios mío!, yo te alabaré eternamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 1, 'Oh Señor, en ti tengo puesta mi esperanza; no quede yo para siempre confundido; sálvame, pues eres justo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 2, 'Dígnate escucharme, acude prontamente a librarme. Sé para mí un Dios tutelar, y un alcázar de refugio para ponerme a salvo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 3, 'Porque tú eres mi fortaleza y mi asilo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 4, 'Tú me sacarás del lazo que me tienen ocultamente armado, pues tú eres mi protector.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 5, 'En tus manos encomiendo mi espíritu; tú me has redimido, ¡oh Señor Dios de la verdad!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 6, 'Tú aborreces a los que se pagan de supersticiones inútiles. Mas yo tengo puesta en el Señor mi esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 7, 'En tu misericordia me regocijaré, y saltaré de gozo. Porque te dignaste volver los ojos a mi abatimiento, y sacaste de apuro mi alma.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 8, 'No me dejaste encerrado en manos del enemigo, sino que abriste ancho camino a mis pies.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 9, 'Apiádate de mí, ¡oh Señor! porque me veo atribulado. Mi vista, mi espíritu, mis entrañas se han conturbado por el pesar o indignación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 10, 'Pues de puro dolor se va consumiendo mi vida y mis años con tanto gemir. Se ha debilitado mi vigor a causa de la miseria, y todos mis huesos se hallan dislocados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 11, 'He venido a ser el oprobio de todos mis enemigos, y principalmente de mis vecinos; y objeto de horror para mis conocidos. Los que me veían, huían lejos de mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 12, 'Fui borrado de su corazón, y puesto en olvido como un muerto; fui considerado como un mueble inútil.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 13, 'Porque yo oía los denuestos de muchos que estaban alrededor mío; los cuales al conjurarse contra mí, trazaron entre ellos quitarme la vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 14, 'Pero yo, Señor, puse en ti mi esperanza. Y tú eres, dije yo, mi Dios;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 15, 'en tus manos está mi suerte. Líbrame del poder de mis enemigos, y de aquellos que me persiguen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 16, 'Derrama sobre tu siervo la luz de tu rostro');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 17, '¡Oh Señor!, no quede yo confundido ya que te he invocado. Queden, sí, avergonzados los impíos, y sean derribados al profundo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 18, 'Enmudezcan los labios fraudulentos, que hablan inicuamente contra el justo con soberbia y menosprecio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 19, '¡Oh, cuán grande es, Señor, la dulzura que tienes reservada para los que te temen! Tú la has comunicado abundantemente, a vista de los hijos de los hombres, a aquellos que tienen puesta en ti su esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 20, 'Tú los esconderás donde está escondido tu rostro, preservándolos de los alborotos de los hombres. Los pondrás en tu Tabernáculo, a cubierto de las lenguas maldicientes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 21, 'Bendito sea el Señor que ha ostentado maravillosamente su misericordia conmigo en la ciudad fortificada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 22, 'Yo, es verdad, que dije en un arrebato de mi genio: Arrojado me hallo de tu vista. Por eso mismo te dignaste oír mi oración, mientras a ti clamaba.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 23, 'Amad al Señor, santos suyos todos; porque el Señor inquirirá la verdad, y dará el pago bien cumplido a los que obran con soberbia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 30, 24, 'Portaos varonilmente todos vosotros los que tenéis puesta en el Señor vuestra esperanza, y tened buen ánimo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 1, 'Alabaré al Señor en todo tiempo, no cesarán mis labios de pronunciar sus alabanzas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 2, 'En el Señor se gloriará mi alma. Oiganlo los humildes, y se consuelen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 3, 'Engrandeced conmigo al Señor, y todos a una ensalcemos su Nombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 4, 'Acudí solícitamente al Señor, y me oyó, y me sacó de todas mis tribulaciones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 5, 'Acercaos vosotros a él, y os iluminará, y no quedaréis sonrojados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 6, 'Clamó este pobre, y el Señor le oyó, y lo libró de todas sus angustias.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 7, 'El ángel del Señor asistirá alrededor de los que le temen, y los librará del mal.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 8, 'Gustad y ved cuán suave es el Señor');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 9, 'Temed al Señor todos vosotros sus santos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 10, 'Los ricos padecieron necesidad y hambre');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 11, 'Venid, hijos, escuchadme, que yo os enseñaré el temor del Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 12, '¿Quién es el hombre que apetece vivir, y que desea ver días dichosos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 13, 'Pues para esto guarda pura tu lengua de todo mal, y no profieran tus labios ningún embuste.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 14, 'Huye del mal, y obra el bien; busca la paz, y empéñate en alcanzarla.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 15, 'El Señor tiene fijos sus ojos sobre los justos, y atentos sus oídos a las plegarias que le hacen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 16, 'Y el rostro del Señor está observando a los que obran mal, para extirpar de la tierra la memoria de ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 17, 'Clamaron los justos, y los oyó el Señor, y los libró de todas sus aflicciones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 18, 'El Señor está al lado de los que tienen el corazón atribulado');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 19, 'Muchas son las tribulaciones de los justos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 20, 'De todos los huesos de ellos tiene el Señor sumo cuidado');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 21, 'Funestísima es la muerte de los pecadores');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 33, 22, 'El Señor redimirá las almas de sus siervos, y no perecerán los que en él esperan.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 1, 'Resolvió el impío en su corazón el hacer el mal');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 2, 'Porque ha obrado dolosamente en la divina presencia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 3, 'Las palabras de su boca son injusticia y embustes');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 4, 'Estando en su lecho discurre cómo obrar la iniquidad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 5, '¡Oh Señor!, llega hasta el cielo tu misericordia, y hasta las nubes tu verdad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 6, 'Como altísimos montes es grande tu justicia, abismo profundísimo tus juicios. A hombres y bestias conservas, ¡oh Señor!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 7, '¡Oh, cuánto has multiplicado, oh Dios, tu misericordia! Por eso los hijos de los hombres esperarán bajo las sombras de tus alas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 8, 'Quedarán embriagados con la abundancia de tu casa, y les harás beber en el torrente de tus delicias.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 9, 'Porque en ti está la fuente de la vida');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 10, 'Despliega tu misericordia sobre los que te conocen, y tu justicia a favor de aquellos que tienen un corazón recto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 11, 'No dé yo pasos de soberbia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 35, 12, 'Allí es donde han caído por tierra los que cometen la maldad; han sido arrojados afuera, y no han podido levantarse más.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 1, 'Oh Señor, no me reprendas en medio de tu saña; ni en medio de tu cólera me castigues.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 2, 'Porque se me han clavado tus saetas y has cargado sobre mí tu mano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 3, 'No hay parte sana en todo mi cuerpo, a causa de tu indignación; se me estremecen los huesos cuando considero mis pecados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 4, 'Porque mis maldades sobrepujan por encima de mi cabeza');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 5, 'Se enconaron y corrompieron mis llagas, a causa de mi necedad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 6, 'Estoy hecho una miseria y encorvado hasta el suelo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 7, 'Porque mis entrañas están llenas de ardor, y no hay en mi cuerpo parte sana.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 8, 'Afligido estoy y abatido en extremo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 9, 'Oh Señor, bien ves todos mis deseos, y no se te ocultan mis gemidos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 10, 'Mi corazón está conturbado');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 11, 'Mis amigos y mis deudos se arrimaron y se apostaron contra mí');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 12, 'Entretanto aquellos que procuraban mi muerte, hacían todos sus esfuerzos; y los que anhelaban dañarme, hablaban mil sandeces; y estaban todo el día maquinando engaños.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 13, 'Pero yo, como si fuera sordo no los escuchaba, y estaba como mudo, sin abrir la boca.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 14, 'Y me hice como quien nada oye, y no tiene palabras con que replicar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 15, 'Porque en ti tengo puesta, Señor, mi esperanza; tú me oirás, ¡oh Señor Dios mío!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 16, 'Pues yo dije: No triunfen sobre mí mis enemigos; los cuales, cuando ven vacilantes mis pies, se vanaglorian contra mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 17, 'Verdad es que yo estoy resignado al castigo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 18, 'Yo mismo confesaré mi iniquidad, y andaré siempre pensativo por causa de mi pecado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 19, 'Entretanto mis enemigos viven, y se han hecho más fuertes que yo; y se han multiplicado los que me aborrecen injustamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 20, 'Los que vuelven mal por bien murmuraban de mí, porque seguía la virtud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 21, '¡Ah! No me desampares, Señor Dios mío; no te apartes de mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 37, 22, 'Acude pronto a socorrerme, ¡oh Señor Dios, salvador mío!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 1, 'Dije yo en mi corazón: Velaré mi conducta para no pecar con mi lengua. Ponía un candado en mi boca, cuando el pecador se presentaba contra mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 2, 'Enmudecí y me humillé, y me abstuve de responder aun cosas buenas; con lo cual se aumentó mi dolor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 3, 'Sentí que se inflamaba mi corazón');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 4, 'Solté mi lengua, diciendo: ¡Ah Señor!, hazme conocer mi fin, y cuál es el número de mis días, para que yo sepa lo que me resta de vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 5, 'Cierto que has señalado a mis días término corto');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 6, 'En verdad que como una sombra pasa el hombre; y por eso se afana y agita en vano. Atesora, y no sabe para quién allega todo aquello.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 7, 'Ahora bien, ¿cuál es mi esperanza? ¿Por ventura no eres tú, oh Señor, en quien está todo mi bien?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 8, 'Líbrame de todas las iniquidades');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 9, 'Enmudecí, y no abrí mi boca, porque todo lo hacías tú.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 10, 'Señor, levanta de mí tu azote.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 11, 'A los recios golpes de tu mano, yo desfallecí cuando me corregías; por el pecado castigaste tú al hombre; e hiciste que su vida se consumiese como araña. Ciertamente que en vano se conturba y agita el hombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 12, 'Oye, Señor, mi oración, y mi súplica; atiende a mis lágrimas; no guardes silencio; puesto que yo soy delante de ti un advenedizo y peregrino como todos mis padres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 38, 13, 'Afloja un poco conmigo, y déjame respirar, antes que yo parta y deje de existir.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 1, 'Con ansia suma estuve aguardando al Señor, y por fin inclinó a mí sus oídos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 2, 'y escuchó benignamente mis súplicas. Y me sacó del lago de la miseria y del inmundo cieno. Y asentó mis pasos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 3, 'Me puso en la boca un cántico nuevo, un cántico en loor de nuestro Dios. Verán estos muchos, y temerán al Señor, y pondrán en él su esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 4, 'Bienaventurado el hombre cuya esperanza toda es el nombre del Señor, y que no volvió sus ojos hacia la vanidad y a las necedades engañosas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 5, 'Muchas son las maravillas que has obrado, ¡oh Señor Dios mío!, y no hay quien pueda asemejarse a ti en tus designios. Me puse yo a referirlos y anunciarlos; exceden todo guarismo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 6, 'Tú no has querido sacrificios ni oblaciones');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 7, 'Yo entonces dije: Aquí estoy; yo vengo, (conforme está escrito de mí al frente del libro de la ley)');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 8, 'para cumplir tu voluntad. Eso he deseado siempre, oh Dios mío; y tengo tu ley en medio de mi corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 9, 'He anunciado tu justicia ante tu pueblo; no tendré jamás cerrados mis labios: Señor, tú lo sabes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 10, 'No he tenido escondida tu justicia en mi corazón');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 11, 'Pero tú, Señor, no alejes de mí tu piedad; tu misericordia y tu fidelidad me han amparado en todo trance.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 12, 'Porque me hallo cercado de males sin número; me sorprendieron mis pecados, y no pude distinguirlos bien; se multiplicaron más que los cabellos de mi cabeza, y mi corazón ha desmayado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 13, '¡Oh! Dígnate, Señor, librarme; vuelve hacia mí tus ojos para socorrerme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 14, 'Queden de una vez confundidos y avergonzados cuantos buscan cómo quitarme la vida');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 15, 'Sufran luego la ignominia que merecen aquellos que me dicen: ¡Ea, ea!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 16, 'Que se regocijen en ti y salten de gozo todos los que te siguen; y aquellos que aman a tu salvador, digan siempre: Glorificado sea el Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 39, 17, 'Yo por mí soy un mendigo y desvalido; pero el Señor tiene cuidado de mí. Tú eres, ¡oh Señor!, mi libertador y protector. No tardes, Dios mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 1, 'Bienaventurado aquel que piensa en el necesitado y en el pobre');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 2, 'Guárdelo el Señor, y confórtelo y hágalo feliz en la tierra, y no lo entregue a discreción de sus enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 3, 'Consuélelo el Señor cuando se halle postrado en el lecho de su dolor; tú mismo, Señor, lo sostenías en su cama en su enfermedad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 4, 'En cuanto a mí dije: Señor, ten lástima de mí; sana mi alma, porque pequé contra ti.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 5, 'Prorrumpían mis enemigos en imprecaciones contra mí: ¿Cuándo morirá éste, decían, y se acabará su memoria?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 6, 'Que si alguno entraba a visitarme, hablaba con mentira, tramando en su corazón iniquidades. Salíase afuera y se confabulaba');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 7, 'con los otros. Susurraban contra mí todos mis enemigos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 8, 'Sentencia inicua pronunciaron contra mí. Mas, ¿por ventura el que duerme no volverá a levantarse?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 9, 'Lo que más es, un hombre con quien vivía yo en dulce paz, de quien yo me fiaba, y que comía de mi pan, ha urdido una gran traición contra mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 10, 'Pero tú, Señor, ten piedad de mí y levántame, que yo les daré a ellos su merecido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 11, 'En esto habré conocido que tú me amas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 12, 'Porque tú me has tomado bajo tu protección a causa de mi inocencia, y me has puesto en lugar seguro ante tu acatamiento por toda la eternidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 40, 13, 'Bendito sea el Señor Dios de Israel por los siglos de los siglos. ¡Amén! ¡Amén!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 1, 'Como busca el sediente ciervo por las fuentes de aguas, así, ¡oh Dios!, clama por ti el alma mía.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 2, 'Sedienta está mi alma del Dios fuerte y vivo. ¡Cuándo será que yo llegue, y me presente ante Dios!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 3, 'Mis lágrimas me han servido de pan día y noche, desde que me están diciendo continuamente: Y tu Dios, ¿dónde está?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 4, 'Estos eran los recuerdos que venían a mi memoria; y ensanché dentro de mí mi espíritu; porque yo he de llegar, dije, al sitio del admirable tabernáculo, hasta la casa de mi Dios; entre voces de júbilo, y de acción de gracias, y de algazara de convite.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 5, '¿Por qué estás triste, oh alma mía?; y ¿por qué me tienes en esta agitación? Espera en Dios; porque aún cantaré sus alabanzas, como que es el salvador que tengo siempre delante de mí,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 6, 'y mi Dios. Conturbada está mi alma. Por lo mismo me acordaré de ti en el país que está desde el Jordán hasta Hermón y el pequeño monte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 7, 'Como el estampido con que se deshacen tus cataratas, un abismo o aguacero llama a otro abismo; así todas tus tempestades y todas tus olas han ido descargando sobre mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 8, 'En el día dispondrá el Señor que venga su misericordia; y yo en la noche cantaré tus alabanzas. Haré para conmigo oración a Dios, autor de mi vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 9, 'Le diré a Dios: Tú eres mi amparo; ¿por qué te has olvidado de mí?; y ¿por qué he de andar yo triste, mientras me aflige el enemigo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 10, 'Mientras se están quebrantando mis huesos, no cesan de insultarme los enemigos míos, que me atormentan; diciéndome todos los días: ¿Y tu Dios, dónde está?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 41, 11, 'Pero, ¡oh alma mía!, ¿por qué estás triste?; ¿por qué me llenas de turbación? Espera en Dios, pues aún he de cantarle alabanzas, por ser él el salvador que está siempre delante de mí, y el Dios mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 1, 'Hirviendo está el pecho mío en sublimes pensamientos. Al rey consagro yo esta obra. Mi lengua es pluma de amanuense que escribe muy ligero.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 2, '¡Oh tú el más gentil en hermosura entre los hijos de los hombres!, derramada se ve la gracia en tus labios; por eso te bendijo Dios para siempre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 3, 'Cíñete al lado tu espada, ¡oh rey potentísimo!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 4, 'Con tu gallardía y hermosura camina, avanza prósperamente, y reina por medio de la verdad, y de la mansedumbre y de la justicia; y tu diestra te conducirá a cosas maravillosas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 5, 'Tus penetrantes saetas traspasarán, oh rey, los corazones de tus enemigos; se rendirán a ti los pueblos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 6, 'El trono tuyo, ¡oh Dios!, permanece por los siglos de los siglos; el cetro de tu reino es cetro de rectitud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 7, 'Amaste la justicia y aborreciste la iniquidad; por eso te ungió, ¡oh Dios!, el Dios tuyo con óleo de alegría, con preferencia a tus compañeros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 8, 'Mirra, áloe y casia exhalan tus vestidos, al salir de las estancias de marfil en que con su olor te han recreado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 9, 'Hijas de reyes son tus damas de honor; a tu diestra está la reina con vestido bordado de oro, y engalanada con varios adornos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 10, 'Escucha, ¡oh hija!, y considera. y presta atento oído, y olvida tu pueblo y la casa de tu padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 11, 'Y el rey se enamorará más de tu beldad; porque él es el Señor Dios tuyo, a quien todos han de adorar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 12, 'Las hijas de Tiro vendrán con dones, y te presentarán humildes súplicas todos los poderosos del pueblo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 13, 'En el interior está la principal gloria o lucimiento de la hija del rey; ella está cubierta de un vestido con varios adornos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 14, 'y recamado con franjas de oro. Serán presentadas al rey las vírgenes que han de formar el séquito de ella');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 15, 'Conducidas serán con fiestas y con regocijos, al templo o palacio del rey serán llevadas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 16, 'En lugar de tus padres te nacerán hijos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 44, 17, 'Estos conservarán la memoria de tu Nombre por todas las generaciones. Por esto los pueblos te cantarán alabanzas eternamente por los siglos de los siglos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 1, 'Dios es nuestro refugio y fortaleza, nuestro defensor en las tribulaciones que tanto nos han acosado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 2, 'Por eso no temeremos aun cuando se conmueva la tierra, y sean trasladados los montes al medio del mar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 3, 'Bramaron y se alborotaron sus aguas, a su furioso ímpetu se estremecieron los montes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 4, 'Un río caudaloso alegra la ciudad de Dios');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 5, 'Está Dios en medio de ella, no será conmovida; la socorrerá Dios ya desde el rayar el alba.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 6, 'Se conturbaron las naciones, y bambolearon los reinos; dio el Señor una voz, y la tierra se estremeció.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 7, 'Con nosotros está el Señor de los ejércitos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 8, 'Venid y observad las obras del Señor, y los prodigios que ha hecho sobre la tierra;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 9, 'cómo ha alejado la guerra hasta el cabo del mundo. Romperá los arcos, hará pedazos las armas, y entregará al fuego los escudos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 10, 'Estad tranquilos, y considerad que yo soy el Dios; ensalzado he de ser entre las naciones, y ensalzado en toda la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 45, 11, 'El Señor de los ejércitos está con nosotros');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 1, 'Naciones todas, dad palmadas de aplauso; gritad alegres a Dios con voces de júbilo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 2, 'Porque excelso es el Señor y terrible, rey grande sobre toda la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 3, 'El nos sometió los pueblos, y puso a nuestros pies las naciones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 4, 'Nos eligió por herencia suya a nosotros, porción bella de Jacob, que tanto amó.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 5, 'Ascendió Dios entre voces de júbilo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 6, 'Cantad, cantad salmos a nuestro Dios; cantad, cantad salmos a nuestro rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 7, 'Porque Dios es el rey de toda la tierra: cantadle salmos sabiamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 8, 'Dios reinará sobre las naciones');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 46, 9, 'Los príncipes de los pueblos se reunirán con el Dios de Abrahán; porque es el Dios protector de la tierra, y en gran manera ha sido ensalzado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 1, 'Grande es el Señor, y dignísimo de alabanza en la ciudad de nuestro Dios, en su monte santo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 2, 'Con júbilo de toda la tierra se ha edificado el santuario en el monte de Sión, la ciudad del gran rey, al lado del septentrión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 3, 'Será Dios conocido en sus casas, cuando haya de defenderla.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 4, 'Porque he aquí que los reyes de la tierra se han coligado y conjurado unánimemente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 5, 'Ellos mismos, cuando la vieron así, quedaron asombrados, llenos de turbación, conmovidos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 6, 'y poseídos de terror. Se apoderaron de ellos dolores como de parto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 7, 'Tú con un viento impetuoso harás pedazos las naves de Tarsis.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 8, 'Como lo oímos, así lo hemos visto en la ciudad del Señor de los ejércitos, en la ciudad de nuestro Dios; la cual ha fundado Dios para siempre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 9, 'Hemos experimentado, ¡oh Dios!, tu misericordia en medio de tu templo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 10, 'Al modo que tu Nombre, ¡oh Dios!, así tu gloria se extiende hasta los últimos términos de la tierra; tu diestra está llena de justicia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 11, 'Alégrese el monte de Sión, y salten de placer las hijas de Judá, ¡oh Señor!, por razón de tus juicios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 12, 'Dad vueltas alrededor de Sión, examinadla por todos lados, y contad sus torres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 13, 'Considerad atentamente su fortaleza, y notad bien sus casas o edificios, para poder contarlo a la generación venidera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 47, 14, 'Porque aquí está Dios, el Dios nuestro, para siempre y por los siglos de los siglos. El nos gobernará eternamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 1, 'Oíd estas cosas, naciones todas; estad atentos vosotros todos los que habitáis la tierra;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 2, 'así los que sois plebeyos, como los que sois nobles, juntos los ricos y los pobres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 3, 'Mi boca proferirá sabiduría, y la meditación de mi espíritu prudencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 4, 'Tendré atento el oído a la parábola o inspiración divina');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 5, '¿Qué es, pues, lo que he de temer yo en el aciago día? La iniquidad de mis pasos que me cercará por todos lados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 6, '¡Ay de aquellos que confían en su poder, y se glorian en sus riquezas!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 7, 'El hermano no redime, ¿cómo redimirá otro hombre? Ninguno podrá ofrecer a Dios cosa que le aplaque,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 8, 'ni precio alguno en rescate de su alma, sino que penará para siempre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 9, 'Y no obstante, vivirá perpetuamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 10, 'No verá él la muerte, cuando ha visto que mueren aun los sabios. ¡Ah!, el insensato y el necio, como todos, perecerán, y dejarán a los extraños sus riquezas,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 11, 'y el sepulcro será su eterna habitación, y sus pabellones pasarán de una a otra generación; esos hombres que dieron sus nombres a sus tierras, pensando eternizarse.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 12, 'Y el hombre, constituido en honor, no ha tenido discernimiento; se ha igualado con las bestias, y se ha hecho como uno de ellas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 13, 'Este proceder suyo es causa de su perdición');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 14, 'Como los rebaños de ovejas serán metidos en el infierno; la muerte se cebará en ellos eternamente. Y los justos tendrán el dominio sobre ellos; y no habrá socorro que les valga en el infierno, después de su pasada gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 15, 'Dios redimirá mi alma del poder del infierno, cuando él me recoja de este mundo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 16, 'Tú no te turbes por más que un hombre se haga rico, y crezca el fausto de su casa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 17, 'Puesto que cuando muera nada llevará consigo, ni le seguirá su gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 18, 'Porque mientras él viva, será alabado; y él te bendecirá cuando le hicieres bien.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 19, 'Entrará al lugar de sus padres, y ya no verá jamás la luz.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 48, 20, 'Porque el hombre, constituido en honor, no tuvo discernimiento; se ha igualado con los irracionales, y se ha hecho semejante a ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 1, 'Cuando, después que pecó con Betsabé, vino a él el profeta Natán. Ten piedad de mí, oh Dios, según la grandeza de tu misericordia; y según la muchedumbre de tus piedades, borra mi iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 2, 'Lávame aun más de mi iniquidad, y límpiame de mi pecado,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 3, '(porque yo reconozco mi maldad, y delante de mí tengo siempre mi pecado;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 4, 'contra ti solo he pecado; y he cometido la maldad delante de tus ojos) a fin de que perdonándome, aparezca justo cuando hables, y quedes victorioso en los juicios que de ti se formen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 5, 'Mira, pues, que fui concebido en iniquidad y que mi madre me concibió en pecado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 6, 'Y mira que tú amas la verdad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 7, 'Me rociarás, Señor, con el hisopo, y seré purificado; me lavarás, y quedaré más blanco que la nieve.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 8, 'Infundirás en mi oído palabras de gozo y de alegría, con lo que se recrearán mis huesos quebrantados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 9, 'Aparta tu rostro de mis pecados, y borra todas mis iniquidades.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 10, 'Crea en mí, ¡oh Dios!, un corazón puro, y renueva en mis entrañas el espíritu de rectitud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 11, 'No me arrojes de tu presencia y no retires de mí tu santo espíritu.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 12, 'Restitúyeme la alegría de tu salvador');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 13, 'Yo enseñaré tus caminos a los malos, y se convertirán a ti los impíos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 14, 'Líbrame de la sangre, ¡oh Dios, Dios salvador mío!, y ensalzará mi lengua tu justicia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 15, '¡Oh Señor!, tú abrirás mis labios; y publicará mi boca tus alabanzas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 16, 'Que si tú quisieras sacrificios, ciertamente te los ofreciera; mas tú no te complaces con solos holocaustos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 17, 'El espíritu compungido es el sacrificio más grato para Dios; no despreciarás, ¡oh Dios mío!, el corazón contrito y humillado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 18, 'Señor, por tu buena voluntad sé benigno para con Sión, a fin de que estén firmes los muros de Jerusalén.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 50, 19, 'Entonces aceptarás el sacrificio de justicia, las ofrendas y los holocaustos; entonces serán colocados sobre tu altar becerros para el sacrificio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 52, 1, 'Se estragaron los hombres y se han hecho abominables por sus maldades. No hay quien obre el bien.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 52, 2, 'Echó Dios desde el cielo una mirada sobre los hijos de los hombres para ver si hay quien conozca, o quien busque a Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 52, 3, 'Pero todos se han descarriado; se han hecho igualmente inútiles; no hay quien obre bien, ni uno siquiera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 52, 4, '¿No caerán, pues, en cuenta de que hay un Dios justiciero todos aquellos que cometen la iniquidad, que devoran a mi pueblo como quien come un pedazo de pan?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 52, 5, 'Ellos no han invocado a Dios; temblaron de miedo allí donde no había que temer. Porque Dios aniquila el poder de los que lisonjean a los hombres. Serán confundidos, porque Dios los desechó de sí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 52, 6, '¡Oh! ¿Quién enviará de Sión al salvador de Israel? Cuando Dios ponga fin al cautiverio de su pueblo, se regocijará Jacob, y saltará de gozo Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 1, 'Oye benigno, ¡oh Dios!, mi oración, y no desprecies mi humilde súplica.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 2, 'Atiende a mi ruego, y escúchame. Me he llenado de tristeza en mi afán, y la turbación se ha apoderado de mí,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 3, 'a la gritería de mi enemigo, y por la persecución de los malvados. Porque me han achacado a mí la iniquidad, y me acosan con sus furores.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 4, 'Me tiembla el corazón en el pecho');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 5, 'El temor y temblor se han apoderado de mí, y me hallo cubierto de tinieblas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 6, 'Por esta razón he dicho: ¡Oh, quién me diera alas como a la paloma para echar a volar, y hallar reposo!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 7, 'He aquí que me alejaría huyendo, y permanecería en la soledad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 8, 'Allí esperaría a aquel que me salvará del abatimiento de ánimo y de tempestad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 9, 'Precipítalos, Señor, divide sus dictámenes; pues veo que la ciudad está llena de iniquidad y discordia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 10, 'Día y noche va dando vueltas sobre sus muros la iniquidad. En medio de ella habita la opresión');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 11, 'y la injusticia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 12, 'En verdad que si me hubiese llenado de maldiciones un enemigo mío, lo hubiera sufrido con paciencia y si me hablase con altanería los que me odian, podría acaso haberme guardado de ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 13, 'Mas tú ¡oh hombre, que aparentabas ser otro yo, mi guía, y mi amigo!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 14, 'Tú que conmigo tomabas el dulce alimento, que andábamos de compañía en la casa de Dios... ¡Ah!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 15, 'Que los arrebate la muerte; y desciendan vivos al infierno; ya que todas las maldades se albergan en sus moradas, en medio de su corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 16, 'Pero yo he clamado a Dios, y el Señor me salvará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 17, 'Tarde y mañana y al mediodía contaré y expondré al Señor mis necesidades, y él oirá benigno mi voz.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 18, 'Sacará a paz y salvo mi vida de los que me asaltan, conjurados en compañía de muchos para perderme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 19, 'Dios me oirá; y aquel que existe antes de todos los siglos los humillará. Ellos están obstinados, y no tienen temor de Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 20, 'Ha extendido el Señor la mano para darles su merecido. Profanaron su alianza');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 21, 'han sido disipados a vista de su rostro airado, y su corazón los alcanzó y castigó. Sus palabras son más suaves que el aceite; pero en realidad son dardos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 22, 'Arroja en el seno del Señor tus ansiedades, y él te sustentará; no dejará al justo en agitación perpetua.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 54, 23, 'Al contrario tú, ¡oh Dios!, dejarás caer a aquellos en el pozo de la perdición. Los hombres sanguinarios y alevosos no llegarán a la mitad de sus días; pero yo, ¡oh Señor!, tengo puesta en ti mi esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 1, 'No destruyas a tu siervo. Ten piedad de mí. ¡Dios mío!, apiádate de mí; ya que mi alma tiene puesta en ti su confianza. A la sombra de tus alas esperaré, hasta que pase la iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 2, 'Clamaré a Dios altísimo, a Dios que tanto bien me ha hecho.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 3, 'Envió desde el cielo a librarme; cubrió de oprobio a los que me traían entre pies. Envió Dios su misericordia y su verdad,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 4, 'y sacó mi alma de entre fuertes leones; lleno de turbación me quedé como adormecido. Porque rejones y flechas son los dientes de los hijos de los hombres, y su lengua tajante espada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 5, '¡Oh Dios mío!, ensálzate tú mismo sobre los cielos, y haz brillar tu gloria por toda la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 6, 'Armado habían ellos un lazo a mis pies, y tenían acobardado mi espíritu. Abrieron delante de mí un hoyo; mas ellos cayeron en él.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 7, 'Mi corazón, ¡oh Dios!, está pronto; dispuesto está mi corazón; yo cantaré y entonaré salmos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 8, 'Ea, levántate, gloria mía, apresúrate, ¡oh salterio y cítara! Yo me levantaré al rayar el alba.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 9, 'Te alabaré, oh Señor, en medio de los pueblos, y te cantaré himnos entre las naciones;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 10, 'porque hasta los cielos ha sido ensalzada tu misericordia, y hasta las nubes tu verdad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 56, 11, '¡Oh Dios mío!, ensálzate tú mismo sobre los cielos, y tu gloria por toda la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 1, 'No destruyas a tu siervo. Si verdaderamente hacéis profesión de la justicia, sean rectos vuestros juicios, ¡oh hijos de los hombres!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 2, 'Mas vosotros obráis inicuamente en vuestro corazón, y empleáis vuestras manos en tramar injusticias en la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 3, 'Los pecadores andan enajenados desde cuando nacieron');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 4, 'Su furor es semejante al de una serpiente; como el del áspid que se hace sordo, que te tapa las orejas,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 5, 'y no quiere escuchar la voz de los encantadores, ni del hechicero por más diestro que sea en los encantamientos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 6, 'Pero Dios les quebrará los dientes dentro de la misma boca');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 7, 'Todos serán reducidos a la nada, como agua que pasa y se disipa; tenso tiene el Señor su arco hasta tanto que sean abatidos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 8, 'Como la cera que se derrite, así serán deshechos; cayó fuego sobre ellos, y no vieron más el sol.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 9, 'Antes que los enemigos, que son, oh justos, vuestras espinas, lleguen a hacerse una zarza, vivos así como están los devorará el Señor en su ira.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 10, 'Se alegrará el justo al ver la venganza');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 57, 11, 'Entonces dirán los hombres: Pues el justo recibe su galardón, es indudable que hay un Dios que ejerce su juicio sobre ellos en la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 1, 'No destruyas a tu siervo. Sálvame, Dios mío de mis enemigos, líbrame de los que me asaltan.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 2, 'Sácame del poder de los que obran inicuamente y libértame de esos hombres sedientos de sangre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 3, 'Que ya ves cómo se han hecho dueños de mi vida');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 4, 'No padezco esto, Señor, por culpa mía, ni por pecado mío; sin iniquidad seguí mi carrera, y enderecé mis pasos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 5, 'Levántate y ven en mi socorro, y considera mi inocencia. Apresúrate, oh Señor, Dios de los ejércitos, Dios de Israel, a vigilar a todas las gentes; no uses de piedad con ninguno de los que cometen la iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 6, 'Ellos volverán hacia la tarde; padecerán hambre como perros, y andarán rondando la ciudad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 7, 'Hablarán a escondidas, teniendo dentro de sus labios como un cuchillo afilado, y dirán: ¿Quién hay que nos oiga?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 8, 'Mas tú, ¡oh Señor!, te reirás de ellos; consideras nada todas las gentes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 9, 'En ti he depositado mi fortaleza; pues tú eres, oh Dios, el defensor mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 10, 'La misericordia de mi Dios se anticipará en mi socorro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 11, 'Me ha mostrado Dios sus designios sobre mis enemigos. ¡Ah! no los mates; no sea que mis pueblos echen la cosa en olvido. Dispérsalos con tu poder, y abátelos, ¡oh Señor!, protector mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 12, 'Por causa del crimen de su boca, por las palabras que profirieron sus labios, y sean ellos mismos presa de su propia soberbia. Y por su blasfemia y horrenda mentira serán inflamados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 13, 'En el día de la desolación serán enviados a la perdición, por la ira de Dios, que los consumirá, y quedarán exterminados. Entonces sabrán que Dios reinará sobre Jacob hasta en los últimos términos de la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 14, 'Retornarán a sus casas oír por la tarde, y estarán hambrientos como perros, y andarán dando vueltas en torno de la ciudad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 15, 'Se esparcirán para buscar de comer; y si no pudieren hartarse, entonces murmurarán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 16, 'Entretanto cantaré yo tu poder, y al amanecer celebraré con júbilo tu misericordia; porque has sido mi defensa y amparo en el día de mi tribulación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 58, 17, '¡Oh protector mío!, a ti cantaré salmos; pues tú oh Dios, eres mi asilo; ¡Dios mío, misericordia mía!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 1, 'Escucha, oh Dios mío, mi súplica; atiende mi oración.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 2, 'Desde los últimos términos de la tierra clamé a ti; cuando mi corazón se hallaba más angustiado, tú me colocaste sobre una alta peña; tú fuiste mi guía.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 3, 'Pues eres mi esperanza y baluarte fortísimo contra el enemigo,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 4, 'habitaré para siempre en tu Tabernáculo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 5, 'Porque tú, Dios mío, has oído mi oración, has concedido la herencia a los que temen tu Nombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 6, 'Añadirás días sobre días a la vida del rey, y prolongarás sus años de generación en generación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 7, 'El permanecerá eternamente en la presencia de Dios. ¿Quién podrá penetrar su misericordia y su verdad?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 60, 8, 'Así es que yo cantaré himnos de alabanza a tu Nombre por los siglos de los siglos, y estaré cumpliendo sin cesar mis votos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 1, '¿Cómo no estará mi alma sometida a Dios, dependiendo de él mi salvación?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 2, 'El es mi Dios y mi salvador; siendo él mi defensa, no seré jamás conmovido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 3, '¿Hasta cuándo estaréis acometiendo a un hombre todos juntos para acabar con él, y derrocarle como a una pared desnivelada, y como a una tapia ruinosa?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 4, 'Mas ellos maquinaron despojarme de lo que más aprecio. Corrí como sediento; ellos hablaban bien de mí con la boca, mas en su corazón me maldecían.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 5, 'Tú, ¡oh alma mía!, mantente sujeta a Dios; pues de él viene mi paciencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 6, 'Porque siendo él, como es, mi Dios y mi salvador, y estando él en mi ayuda, no vacilaré.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 7, 'En Dios está mi salvación y mi gloria');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 8, 'Esperad en él vosotros, pueblos todos aquí congregados; derramad vuestros corazones en su acatamiento: Dios es nuestro protector eternamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 9, 'Al contrario, vanos y falaces son los hijos de los hombres; mentirosos son los hijos de los hombres puestos en balanza; todos ellos juntos son más livianos que la misma vanidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 10, 'No queráis confiar en la justicia, ni codiciar robos; aun si las riquezas os vienen en abundancia, no pongáis en ella vuestro corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 11, 'Una vez habló Dios, y estas dos cosas oí yo: Que el poder está en Dios,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 61, 12, 'y que tú, Señor, eres misericordioso; porque a cada uno remunerarás conforme a sus obras.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 1, '¡Dios mío, oh mi Dios!, a ti aspiro, y me dirijo desde que apunta la aurora. De ti está sedienta el alma mía. ¡Y de cuántas maneras lo está también este mi cuerpo!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 2, 'En esta tierra desierta, intransitable y sin agua, me pongo en tu presencia, como si me hallara en el santuario, para contemplar tu poder y la gloria tuya.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 3, 'Más apreciable es que mil vidas tu misericordia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 4, 'Por esto te bendeciré toda mi vida, y alzaré mis manos invocando tu Nombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 5, 'Quede mi alma bien llena de ti, como de un manjar jugoso; y entonces con labios que rebosen de júbilo, te cantará mi boca himnos de alabanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 6, 'Me acordaba de ti en mi lecho');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 7, 'pues tú eres mi amparo, y a la sombra de tus alas me regocijaré.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 8, 'En pos de ti va anhelando el alma mía');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 9, 'En vano han buscado cómo quitarme la vida');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 10, 'Entregados serán a los filos de la espada');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 62, 11, 'Entretanto el rey se regocijará en Dios: loados serán aquellos que le juran');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 1, 'Escucha oh Dios mío, mi oración, cuando a ti clamo; libra mi alma del temor que me causa el enemigo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 2, 'Tú me has defendido de la conspiración de los malignos, del tropel de los que obran la iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 3, 'Ellos aguzaron sus lenguas como espada; asestaron su arco emponzoñado,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 4, 'para asaetear desde una emboscada al inocente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 5, 'De repente le harán el tiro, sin temor alguno; obstinados en su infame designio, trataron de armar ocultos lazos, y dijeron: ¿Quién los podrá descubrir?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 6, 'Discurrieron mil invenciones para hacer el mal');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 7, 'Mas Dios será ensalzado. Las heridas que ellos hagan son como las que hacen las flechas que disparan los niños.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 8, 'Y sus lenguas han flaqueado contra ellos mismos. Quedaron asombrados cuantos los veían,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 9, 'y no hubo quien se atemorizase. Con lo cual publicaron todos las obras de Dios y meditaron sobre sus hechos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 63, 10, 'Se alegrará el justo en el Señor, y esperará en él; y serán aplaudidos todos los de recto corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 1, 'Dios tenga misericordia de nosotros y nos bendiga; haga resplandecer sobre nosotros la luz de su rostro, y nos mire compasivo;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 2, 'para que conozcamos, oh Señor, en la tierra tu camino, y en todas las naciones tu salvación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 3, 'Que te alaben, Dios mío, los pueblos; y publiquen todos los pueblos tus alabanzas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 4, 'Que se regocijen, salten de gozo las naciones, porque tú juzgas a los pueblos con justicia, y diriges las naciones sobre la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 5, 'Que te alaben, oh Dios mío, los pueblos; y publiquen todos los pueblos tus alabanzas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 6, 'Ha dado la tierra su fruto. Bendíganos Dios, el Dios nuestro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 66, 7, 'Bendíganos Dios, y sea temido en todos los confines de la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 1, 'Levántese Dios, y sean disipados sus enemigos, y huyan de su presencia los que le aborrecen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 2, 'Desaparezcan como el humo. Como se derrite la cera al calor del fuego, así perezcan los pecadores a la vista de Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 3, 'Mas los justos celebren con alegría festines y regocijos en la presencia de Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 4, 'Cantad himnos a Dios; entonad salmos a su Nombre; allanad el camino al que sube sobre el occidente. El Señor o Yahvé es el nombre suyo. Saltad de gozo en su presencia. Se turbarán los impíos delante de él,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 5, 'que es el padre de los huérfanos y el juez defensor de las viudas. Reside Dios en su lugar santo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 6, 'Dios que hace habitar dentro de una casa muchos de unas mismas costumbres, que con su fortaleza pone en libertad a los prisioneros, como también a los que irritan, los cuales moran en los sepulcros o lugares áridos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 7, '¡Oh Dios!, cuando tú salías al frente de tu pueblo, cuando atravesabas el desierto,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 8, 'la tierra tembló, y hasta los cielos destilaron a la presencia de Dios; en el Sinaí tembló a la presencia del Dios de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 9, '¡Oh Dios! tú distribuirás una lluvia abundante y apacible a tu heredad; ella se ha visto afligida, pero tú la has recreado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 10, 'En ella tendrán morada los que son de tu grey; con tu bondad, oh Dios mío has provisto de alimento al pobre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 11, 'El Señor dará palabras a los que anuncian con valor la buena nueva.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 12, 'Los reyes poderosos serán súbditos de su Hijo muy amado, y aquel Señor que es la hermosura de la casa repartirá los despojos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 13, 'Cuando durmiereis en medio de peligros, seréis como alas de paloma plateadas cuyas plumas por la espalda echan brillos de oro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 14, 'Cuando el rey celestial ejerza su juicios sobre los reyes de la tierra, quedarán más blancos que la nieve del monte Selmón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 15, '¡Oh Sión, monte de Dios, monte fértil, monte cuajado, monte fecundo!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 16, 'Mas ¿por qué andáis pensando en otros montes fértiles? Este es el monte donde Dios se complació en fijar su morada. Sí');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 17, 'La carroza de Dios va acompañada de muchas docenas de millares de tropas, de millones de ángeles que hacen fiesta. En medio de ellos está el Señor, en el Sinaí, en el lugar santo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 18, 'Ascendiste, Señor, a lo alto, llevaste contigo a los cautivos; recibiste dones para los hombres; aun para aquellos que no creían que habitase el Señor Dios entre nosotros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 19, 'Bendito sea el Señor todos los días');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 20, 'Nuestro Dios es el Dios que tiene la virtud de salvarnos; y del Señor, y muy del Señor, es librar de la muerte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 21, 'Mas Dios quebrantará las cabezas de sus enemigos, el copete erizado de los que hacen pompa de sus delitos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 22, 'Dijo el Señor: A los de Basán les haré volver las espaldas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 23, 'Serán destrozados hasta teñirse tus pies en la sangre de tus enemigos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 24, 'Vieron, ¡oh Dios!, tu entrada, la entrada de mi Dios, del rey mío que reside en el santuario.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 25, 'Iban delante los príncipes unidos a los que cantaban y en medio doncellitas tocando panderos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 26, '¡Oh vosotros!, decían, descendientes de Israel, bendecid al Señor Dios en vuestras asambleas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 27, 'Allí se hallaba la tribu del jovencito Benjamín como extática de gozo; los jefes de Judá iban de guías; los jefes de Zabulón, los jefes de Neftalí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 28, 'Muestra, ¡oh Dios!, tu poderío; confirma, ¡oh Dios!, esta obra, que has hecho en nosotros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 29, 'Por respeto a tu templo en Jerusalén, te ofrecerán dones los reyes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 30, 'Reprime esas fieras que habitan en los cañaverales, esos pueblos reunidos, que, como toros dentro de la vacada, conspiran para echar fuera a los que han sido acrisolados como la plata. Disipa las naciones que quieren guerras.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 31, 'Entonces Egipto enviará embajadores');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 32, 'Cantad, pues, alabanzas a Dios, ¡oh reinos de la tierra!, load al Señor con salmos. Cantadle salmos a Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 33, 'El cual se elevó al más alto de los cielos, desde el oriente. Sabed que desde allí hará que su voz sea una voz todopoderosa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 34, 'Tributad, pues, gloria a Dios por lo que ha obrado en Israel; su magnificencia y su poder se elevan hasta las nubes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 67, 35, 'Admirable es Dios en sus santos, o en su santuario; el Dios de Israel, él mismo dará virtud y fortaleza a su pueblo. Bendito sea Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 1, 'Sálvame, oh Dios, porque las aguas han penetrado hasta mi alma.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 2, 'Atollado estoy en mi profundísimo cieno, sin hallar dónde afirmar el pie. Llegué a alta mar, y me sumergió la tempestad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 3, 'Me fatigué en dar voces');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 4, 'Se han multiplicado, más que los cabellos de mi cabeza, los que me aborrecen injustamente. Se han hecho fuertes mis enemigos, los injustos perseguidores míos; he pagado lo que yo no había robado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 5, 'Tú, ¡oh Dios mío!, sabes mi ignorancia, y los delitos que yo tenga no se te pueden ocultar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 6, '¡Ah! no tengan que avergonzarse por mi causa aquellos que en ti confían, ¡oh Señor, Señor de los ejércitos! No queden corridos por causa mía los que van en pos de ti, ¡oh Dios de Israel!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 7, 'Pues por amor a ti he sufrido los ultrajes, y se ve cubierto de confusión el rostro mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 8, 'Mis propios hermanos, los hijos de mi misma madre, me han desconocido y tenido por extraño.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 9, 'Porque el celo de tu casa me devoró, y los baldones de los que te denostaban recayeron sobre mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 10, 'Me afligía con el ayuno, y se me convertía en afrenta.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 11, 'Me vestía de cilicio, y me hacía la fábula de ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 12, 'Contra mí se declaraban los que tienen su asiento en la puerta');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 13, 'Mas yo entretanto, Señor, dirigía a ti mi oración. Este es, decía, ¡oh Dios mío!, el tiempo de reconciliación. Oyeme benigno según la grandeza de tu misericordia, conforme a tu promesa fiel de salvarme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 14, 'Sácame del cieno, para que no quede yo atascado en él; líbrame de aquellos que me aborrecen y del profundo de las aguas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 15, 'No me anegue esta tempestad, ni me trague el abismo del mar, ni el pozo cierre sobre mí su boca.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 16, 'Oyeme, Señor, ya que tan benéfica es tu misericordia; vuelve hacia mí tus ojos según la grandeza de tu piedad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 17, 'Y no pierdas de vista a tu siervo; oye presto mis súplicas, porque me veo atribulado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 18, 'Mira por mi alma y líbrala');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 19, 'Bien ves los oprobios que sufro, y mi confusión, y la ignominia mía.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 20, 'Tienes ante tus ojos todos los que me atormentan; improperios y miserias aguarda siempre mi corazón. Esperé que alguno se condoliese de mí, mas nadie lo hizo; o quien me consolase, y no hallé quien lo hiciese.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 21, 'Me presentaron hiel para alimento mío, y en medio de mi sed me dieron a beber vinagre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 22, 'En justo pago se les convierta su mesa en lazo de perdición y ruina.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 23, 'Oscurece sus ojos para que no vean');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 24, 'Derrama sobre ellos tu ira, y que los alcance el furor de tu cólera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 25, 'Quede hecha un desierto su morada, y no haya quien habite en sus tiendas,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 26, 'ya que han perseguido a aquel que tú habías herido, y aumentaron más y más el dolor de mis llagas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 27, 'Tú permitirás que añadan pecados a pecados, y no acierten con tu justicia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 28, 'Raídos sean del libro de los vivientes, y no queden escritos en el libro de los Justos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 29, 'Yo soy un miserable y lleno de dolores; mas tú, oh Dios mío, me has salvado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 30, 'Alabaré con cánticos el nombre de Dios, y le ensalzaré con acciones de gracias,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 31, 'lo que será más grato a Dios que si le inmolara un ternerillo cuando le comienzan a salir las astas y las pezuñas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 32, 'Que vean esto los pobres, y se consuelen. Buscad, pues, a Dios, y revivirá vuestro espíritu,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 33, 'puesto que el Señor oyó a los pobres, y no olvidó a los que están por él en cadenas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 34, 'Que lo alaben los cielos y la tierra, el mar y cuanto en ellos se mueve.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 35, 'Porque Dios salvará a Sión, y las ciudades de Judá serán reedificadas; y establecerán allí su morada, y las adquirirán como herencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 68, 36, 'Y los descendientes de sus fieles siervos las poseerán');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 69, 1, 'Oh Dios, atiende a mi socorro; acude, Señor, luego a ayudarme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 69, 2, 'Corridos y avergonzados queden los que me persiguen de muerte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 69, 3, 'Que se arredren, y se confundan los que se complacen en mis males. Sean puestos en vergonzosa fuga aquellos que me dicen insultándome: ¡Bueno, bueno!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 69, 4, 'Que se regocijen, y se alegren en ti todos los que te buscan; y digan sin cesar los que aman a su salvador: Engrandecido sea el Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 69, 5, 'Yo por mí soy un menesteroso y pobre; ayúdame, oh Dios. Amparo mío y mi libertador eres tú; ¡oh Señor!, no tardes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 1, 'Profeta. Te alabaremos, oh Dios, te bendeciremos e invocaremos tu Nombre. Publicaremos tus maravillas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 2, 'Dios. Cuando llegare mi tiempo, yo juzgaré con justicia todas las cosas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 3, 'Se derretirá la tierra con todos sus habitantes. Yo fui quien dio firmeza a sus columnas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 4, 'Profeta. Dije a los malvados: No queráis cometer más la maldad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 5, 'No levantéis con insolencia vuestras cabezas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 6, 'Porque ni por el oriente, ni por el occidente, ni por los desiertos montes tendréis escape,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 7, 'pues el juez es Dios. El abate a uno, y ensalza a otro;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 8, 'porque el Señor tiene en la mano un cáliz de vino puro, lleno de amarga mistura, y le hace pasar de uno a otro; mas no por eso se han apurado sus últimos tragos, las han de beber todos los pecadores de la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 9, 'Yo anunciaré y cantaré eternamente las alabanzas al Dios de Jacob.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 74, 10, 'Dios. Y yo abatiré todo el orgullo de los pecadores, y haré que los justos levanten la cabeza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 1, 'Dios es conocido en la Judea');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 2, 'Fijó su habitación en la paz, y su morada en Sión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 3, 'Allí rompió las saetas y los arcos, los escudos, las espadas; y puso fin a la guerra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 4, 'Alumbrando tú maravillosamente desde los montes eternos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 5, 'quedaron perturbados todos los de corazón insensato. Durmieron su sueño; y todos esos hombres, opulentos se encontraron sin nada, vacías sus manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 6, 'Al trueno de tu amenaza, ¡oh Dios de Jacob !, se quedaron sin sentido los que montaban briosos caballos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 7, 'Terrible eres tú, ¡oh Señor!, ¿y quién podrá resistirte a ti desde el momento de tu ira?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 8, 'Desde el cielo hiciste oír tu sentencia; la tierra tembló, y se quedó suspensa,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 9, 'al levantarse Dios a juicio para salvar a todos los mansos de la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 10, 'El hombre que esto medite, te alabará; y en consecuencia de sus meditaciones, celebrará fiestas en honor tuyo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 11, 'Ofreced y cumplid votos al Señor Dios vuestro, todos vosotros, los que estando alrededor de él le presentáis dones;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 75, 12, 'al Dios terrible, al que quita el aliento a los príncipes, al terrible para los reyes de la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 1, 'Alcé mi voz y clamé al Señor, a Dios clamé, y me atendió.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 2, 'En el día de mi tribulación acudí solícito a Dios, levanté por la noche mis manos hacia él, y no quedé burlado. Se había negado mi alma a todo consuelo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 3, 'Me acordé de Dios, y me sentí bañado de gozo; me ejercité en la meditación, y caí en un desfallecimiento.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 4, 'Estuvieron mis ojos abiertos antes de la madrugada');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 5, 'Me puse a considerar los días antiguos, y a meditar en los años eternos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 6, 'En esto me ocupaba allá en mi corazón durante la noche, y lo rumiaba, y examinaba mi interior.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 7, '¿Es posible, decía, que Dios nos haya de abandonar para siempre, o no haya de volver a sernos propicio?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 8, '¿O que haya de privar eternamente de su misericordia a todas las gentes venideras?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 9, '¿Se olvidará Dios de usar de clemencia?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 10, 'Entonces dije: Ahora comienzo a respirar. De la diestra del Altísimo me viene esta mudanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 11, 'Traeré a la memoria las obras del Señor. Sí, por cierto, haré memoria de las maravillas que has hecho desde el principio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 12, 'Y meditaré todas tus obras, y consideraré tus designios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 13, '¡Oh Dios!, santo es tu camino. ¿Qué dios hay que sea grande como el Dios nuestro?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 14, 'Tú eres el Dios autor de los prodigios. Tú hiciste manifiesto a los pueblos tu poderío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 15, 'Con tu brazo redimiste a tu pueblo, a los hijos de Jacob y de José.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 16, 'Te vieron las aguas, ¡oh Dios!; te vieron las aguas, y se llenaron de temor y se estremecieron los abismos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 17, 'Grande fue el estruendo de las aguas, tronaron las nubes, atravesaron tus rayos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 18, 'girando en torno la voz de tus truenos. Relumbraron tus relámpagos por toda la tierra, toda ella se estremeció, y tembló.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 19, 'Te abriste camino dentro del mar; caminaste por en medio de muchas aguas, y no se conocerán los vestigios de tus pisadas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 76, 20, 'Condujiste a tu pueblo, como otras tantas ovejas, por el ministerio de Moisés y Aarón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 1, 'Escucha, ¡oh tú, pastor de Israel!, tú que apacientas el pueblo de José, como a ovejas. Tú que estás sentado sobre los querubines, manifiéstate,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 2, 'delante de Efraín, de Benjamín y de Manasés. Ostenta tu poder, y ven a salvarnos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 3, '¡Oh Dios!, conviértenos a ti, y muéstranos favorable tu semblante; y seremos salvos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 4, '¡Oh Señor Dios de los ejércitos!, ¿hasta cuándo estarás enojado sin escuchar la oración de tu siervo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 5, '¿Hasta cuándo nos has de alimentar con pan de lágrimas, y hasta cuándo nos darás a beber lágrimas con abundancia?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 6, 'Nos haces el blanco de la contradicción de nuestros vecinos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 7, '¡Oh Dios de los ejércitos!, conviértenos a ti, y muéstranos tu rostro, y seremos salvos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 8, 'De Egipto trasladaste acá tu viña; arrojaste las naciones, y la plantaste.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 9, 'Fuiste delante de ella en el viaje, para irla guiando; la hiciste arraigar, y llenó la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 10, 'Cubrió con su sombra los montes, y los altísimos cedros con sus sarmientos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 11, 'Hasta el mar extendió sus pámpanos, y hasta el río sus vástagos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 12, '¿Por qué has derribado su cerca, y dejas que la vendimien todos los caminantes?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 13, 'El jabalí del bosque la ha destruido, y se apacienta en ella esa fiera solitaria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 14, '¡Oh Dios de los ejércitos! vuélvete hacia nosotros, mira desde el cielo, y atiende y visita esa viña.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 15, 'Renuévala, pues la plantó tu diestra; y en atención al hijo del hombre, a quien tú te escogiste.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 16, 'Ella ha sido entregada a las llamas y desarraigada');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 17, 'Tiende tu mano protectora sobre el varón de tu diestra, sobre el hijo del hombre a quien tú escogiste.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 18, 'Entonces no nos apartaremos de ti; nos darás nueva vida, e invocaremos tu Nombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 79, 19, '¡Oh Señor Dios de los ejércitos!, conviértenos a ti, y muéstranos tu rostro, y seremos salvos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 1, 'Regocijaos, alabando a Dios nuestro protector; celebrad con júbilo al Dios de Jacob.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 2, 'Entonad salmos, tocad el pandero; el armonioso salterio junto con la cítara.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 3, 'Tocad las trompetas el Novilunio, el gran día de vuestra solemnidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 4, 'Pues es un precepto dado a Israel, y un rito instituido por el Dios de Jacob.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 5, 'Le impuso para que sirviese de memoria a los descendientes de José, al salir de la tierra de Egipto, cuando oyeron una lengua que no entendían.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 6, 'Libertó sus hombros de las cargas, y sus manos de las espuertas con que servían en las obras.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 7, 'En la turbación, dice el Señor, me invocaste, y yo te libré; te oí benigno en la oscuridad de la tormenta; hice prueba de ti junto a las aguas de la contradicción.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 8, 'Escucha, pueblo mío, y yo te instruiré. ¡Oh Israel!, si quieres obedecerme,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 9, 'no habrá en tu distrito dios nuevo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 10, 'Porque yo soy el Señor Dios tuyo, que te saqué de la tierra de Egipto; abre bien tu boca, que yo te saciaré plenamente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 11, 'Pero mi pueblo no quiso escuchar la voz mía');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 12, 'Y así los abandoné, dejándolos ir en pos de los deseos de su corazón, y seguir sus devaneos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 13, '¡Ah si mi pueblo me hubiese oído a mí, si hubiesen seguido los hijos de Israel por mis caminos!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 14, 'Como quien no hace nada, hubiera yo seguramente humillado a sus enemigos, y descargado mi mano sobre sus perseguidores.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 15, 'Pero, hechos enemigos del Señor, le faltaron a la promesa; y el tiempo de ellos, o su suplicio, será eterno.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 80, 16, 'Sin embargo, los sustentó con riquísimo trigo, y los sació con la miel que destilaban las peñas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 1, '¡Oh Dios! ¿Quién hay semejante a ti? No estés así en silencio; no te contengas, Dios mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 2, 'Ya ves cuánto ruido meten tus enemigos, y cómo andan con la cabeza erguida los que te aborrecen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 3, 'Urdieron contra tu pueblo malvados designios, y han maquinado contra tus santos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 4, 'Venid, dijeron, y borremos esa gente de la lista de las naciones, y no quede más memoria del nombre de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 5, 'Por este motivo todos unánimes se han coligado');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 6, 'los pabellones de los idumeos y los ismaelitas, Moab y los agarenos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 7, 'Gebal, y Amón, y Amalec, los filisteos con los tirios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 8, 'Se unió también con ellos el asirio, y lo hizo auxiliador de los hijos de Lot.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 9, 'Pero tú, Señor, haz con ellos lo que con los madianitas y con Sísara, lo mismo que con Jabín en el torrente de Cisón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 10, 'Perecieron ellos en Endor');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 11, 'Trata a sus caudillos como a Oreb y Zeb, y como a Zebee y a Salmana, a todos sus príncipes,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 12, 'los cuales han dicho: Apoderémonos del santuario de Dios como heredad que nos pertenece.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 13, 'Agítalos, ¡oh Dios mío!, como a una rueda, o como la hojarasca al soplo del viento;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 14, 'como fuego que abrasa una selva, cual llama que devora los montes,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 15, 'así los perseguirás con el soplo de tu tempestad, y en medio de tu ira los aterrarás.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 16, 'Cubre sus rostros de ignominia; que así, ¡oh Señor!, reconocerán tu Nombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 17, 'Que se avergüencen, y sean conturbados para siempre; queden corridos, y perezcan.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 82, 18, 'Y conozcan que te es propio el nombre del Señor, y que sólo tú eres el Altísimo en toda la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 1, '¡Oh cuán amables son tus moradas, Señor de los ejércitos!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 2, 'Mi alma suspira y padece desfallecimientos, ansiando estar en los atrios del Señor. Se transportan de gozo mi corazón y mi cuerpo, contemplando al Dios vivo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 3, 'El pajarillo halló un hueco donde guarecerse, y nido la tórtola para poner sus polluelos. Tus altares, oh Señor de los ejércitos, oh rey mío y Dios mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 4, 'Bienaventurados, Señor, los que moran en tu casa, te alabarán por los siglos de los siglos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 5, 'Dichoso el hombre que en ti tiene su amparo, y que ha dispuesto en su corazón,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 6, 'en este valle de lágrimas, los grados para subir hasta el lugar santo que destinó Dios para sí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 7, 'Porque le dará su bendición el legislador, y caminarán de virtud en virtud; y el Dios de los dioses se dejará ver en Sión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 8, '¡Oh Señor Dios de los ejércitos! oye mi oración; escúchala atento, oh Dios de Jacob.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 9, 'Vuélvete a mirarnos, ¡oh Dios protector nuestro!, y pon los ojos en el rostro de tu Ungido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 10, 'Más vale un solo día de estar en los atrios de tu templo, que millares fuera de ellos. He escogido ser el ínfimo en la casa de Dios, más bien que habitar en la morada de los impíos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 11, 'Porque Dios ama la misericordia y la verdad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 83, 12, 'No dejará sin bienes a los que proceden con inocencia. ¡Oh Señor de los ejércitos!, bienaventurado el hombre que pone en ti su esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 1, '¡Oh Señor! tú has derramado la bendición sobre tu tierra');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 2, 'Has perdonado las maldades de tu pueblo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 3, 'Has aplacado ya toda tu ira');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 4, 'Conviértenos, ¡oh Dios, salvador nuestro!, y aparta tu ira de nosotros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 5, '¿Estarás por ventura siempre enojado con nosotros? ¿Se prolongará tu ira de generación en generación?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 6, 'Oh Dios, volviendo tú el rostro hacia nosotros, nos darás vida; y tu pueblo se regocijará en ti.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 7, 'Muéstranos, Señor, tu misericordia, y danos tu salud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 8, 'Haz que escuche yo aquello que me hablará el Señor Dios; pues él anunciará la paz a su pueblo, y a sus santos, y a los que se convierten de corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 9, 'Así es que su salud estará cerca de los que le temen y adoran');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 10, 'Se encontraron juntas la misericordia y la verdad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 11, 'La verdad brotó en la tierra, y la justicia nos ha mirado desde lo alto del cielo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 12, 'Por lo que derramará el Señor su benignidad y nuestra tierra producirá su fruto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 84, 13, 'La justicia marchará delante de él, y dirigirá sus pasos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 1, 'Cantando estaré eternamente la misericordia del Señor. A hijos y nietos haré notoria por mi boca tu fidelidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 2, 'Porque tú dijiste: La misericordia estará eternamente firme en los cielos, y en ellos tendrá seguro apoyo tu veracidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 3, 'Tengo hecha alianza, dijiste, con mis escogidos; he jurado a David, siervo mío, diciendo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 4, 'Apoyaré eternamente tu descendencia, y haré estable tu trono de generación en generación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 5, '¡Oh Señor!, los cielos celebrarán tus maravillas, como también tu verdad en la congregación de los santos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 6, 'Porque, ¿quién hay en los cielos, que pueda igualarse con el Señor?; ¿quien entre los hijos de Dios es semejante a él?;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 7, '¿a Dios, al cual ensalza y glorifica toda la corte de los santos, grande y terrible sobre todos los que asisten en torno de él?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 8, '¿Quién como tú, oh Señor Dios de los ejércitos? Poderoso eres, Señor, y está siempre en torno a ti tu verdad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 9, 'Tú tienes señorío sobre la bravura del mar');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 10, 'Tú abatiste al soberbio, como a uno que está herido de muerte; con tu fuerte brazo disipaste tus enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 11, 'Tuyos son los cielos, y tuya es la tierra, tú fundaste el mundo y cuanto él contiene.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 12, 'El aquilón y el mar tú los creaste. El Tabor y el Hermón saltarán de gozo en tu Nombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 13, 'Lleno de fortaleza está tu brazo. Ostente su robustez la mano tuya, y sea ensalzada tu diestra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 14, 'Justicia y equidad son las bases de tu trono. La misericordia y la verdad van siempre delante de ti.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 15, 'Dichoso el pueblo que sabe alegrarse en ti. ¡Oh Señor!, a la luz de tu rostro caminarán tus hijos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 16, 'y todo el día se regocijarán en tu Nombre, y mediante tu justicia serán ensalzados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 17, 'Puesto que tú eres la gloria de tu fortaleza, y por tu buena voluntad se ensalzará nuestro poder.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 18, 'Porque nos ha tomado por suyos el Señor, y el Santo de Israel que es nuestro rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 19, 'Entonces hablaste en visión a tus santos, y dijiste: Yo tengo preparado en un hombre poderoso el socorro; y he ensalzado a aquel que escogí de entre mi pueblo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 20, 'Hallé a David, siervo mío, lo ungí con mi óleo sagrado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 21, 'Mi mano lo protegerá, y fortalecerlo ha mi brazo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 22, 'Nada podrá adelantar contra él el enemigo, no podrá ofenderle más el hijo de la iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 23, 'Y exterminaré de su presencia a sus enemigos, y pondré en fuga a los que lo aborrecen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 24, 'Le acompañarán mi verdad y mi clemencia, y en mi Nombre será exaltado su poder.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 25, 'Y extenderé su mano sobre el mar, y su diestra sobre los ríos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 26, 'El me invocará, diciéndome: Tú eres mi padre, mi Dios, y el autor de mi salud;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 27, 'y yo le constituiré a él primogénito, y el más excelso entre los reyes de la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 28, 'Eternamente le conservaré mi misericordia, y la alianza mía con él será estable.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 29, 'Haré que subsista su descendencia por los siglos de los siglos, y su trono mientras duren los cielos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 30, 'Que si sus hijos abandonaren mi ley, y no procedieren conforme a mis preceptos;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 31, 'si violaren mis justas disposiciones, y dejaren de observar mis mandamientos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 32, 'yo castigaré con la vara de mi justicia sus maldades, y con el azote sus pecados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 33, 'Mas no retiraré de él mi misericordia, ni faltaré jamás a la verdad de mis promesas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 34, 'No violaré mi alianza, ni retractaré las promesas que han salido de mi boca.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 35, 'Una vez para siempre juré por mi santo Nombre, que no faltaré a lo que he prometido a David:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 36, 'Su linaje durará eternamente,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 37, 'y su trono resplandecerá para siempre en mi presencia, como el sol, y como la luna llena, y como el arco iris, testimonio fiel en el cielo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 38, 'Con todo eso, Señor, tú has desechado y despreciado a tu ungido; te has irritado contra él.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 39, 'Has anulado la alianza con tu siervo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 40, 'Todas sus cercas las has destruido, y su fortaleza la has convertido en espanto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 41, 'Lo saquean cuantos pasan por el camino');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 42, 'Has exaltado el poder de los que le oprimen, y llenado de contento a todos sus enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 43, 'Tienes embotados los filos de su espada, y no le has auxiliado en la guerra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 44, 'Aniquilaste su esplendor, y has hecho pedazos su solio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 45, 'Has acortado los floridos días de su vida');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 46, '¿Hasta cuándo, Señor, te has de mostrar adverso? ¿Hasta cuándo arderá como fuego tu indignación?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 47, 'Acuérdate cuán débil es mi ser. ¿Acaso tú has creado en vano todos los hijos de los hombres?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 48, '¿Qué hombre hay que haya de vivir sin ver jamás la muerte? ¿Quién podrá sacar su alma del poder del infierno o de la muerte?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 49, '¿Señor, dónde está tu antigua misericordia, que prometiste con juramento a David, tomando tu verdad por testigo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 50, 'Ten presente, ¡oh Señor!, los oprobios que tus siervos han sufrido de varias naciones, oprobios que tengo sellados en mi pecho;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 51, 'oprobios con que nos dan en rostro, Señor, tus enemigos, quienes nos echan en cara la mutación de tu ungido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 88, 52, 'Bendito sea el Señor para siempre. ¡Amén! ¡Amén!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 1, 'Bueno es tributar alabanzas al Señor; y salmear a tu Nombre, ¡oh Altísimo!,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 2, 'celebrando por la mañana tu misericordia, y por la noche tu verdad;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 3, 'acompañando el canto con el salterio, y con el sonido de la cítara.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 4, 'Porque me has recreado, oh Señor, con tus obras, y al contemplar las obras de tus manos salto de placer.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 5, '¡Cuán grandes son, Señor tus obras! ¡Cuán insondable la profundidad de tus designios!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 6, 'El hombre insensato no conoce estas cosas, ni entiende de ellas el necio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 7, 'Apenas los pecadores brotarán como el heno, y brillarán todos los malvados, cuando perecerán para siempre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 8, 'Pero tú, ¡oh Señor!, serás eternamente el Altísimo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 9, 'Así es, Señor, que tus enemigos, sí, tus enemigos perecerán, y quedarán disipados cuantos cometen la maldad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 10, 'Y mi fortaleza se levantará como la del unicornio, y mi vejez será vigorizada por tu misericordia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 11, 'Y miraré con desprecio a mis enemigos, y oiré hablar sin susto de los revoltosos que maquinan contra mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 12, 'Florecerá como la palma el varón justo, y descollará cual cedro del Líbano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 13, 'Plantados los justos en la casa del Señor, en los atrios de la casa de nuestro Dios florecerán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 14, 'Y aun en su lozana vejez se multiplicarán; y se hallarán con vigor y robustez,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 91, 15, 'para predicar que el Señor Dios nuestro es justo, y que no hay en él ni sombra de iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 1, 'Dispuesto está mi corazón, oh Dios, mi corazón está dispuesto; cantaré y entonaré salmos en medio de mi gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 2, 'Despierta, pues, ¡oh gloria, oh alma mía!, apresuraos, ¡oh salterio y cítara!, yo me levantaré al rayar la aurora,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 3, 'y te alabaré, Señor en medio de los pueblos, y te cantaré himnos entre las naciones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 4, 'Porque es más grande que los cielos tu misericordia, y más elevada que las nubes la verdad tuya.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 5, 'Ensálzate, ¡oh Dios! sobre los cielos, y ensalza sobre toda la tierra tu gloria; para que obtengan la libertad los que tú amas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 6, 'Sálvame con tu diestra, y atiéndeme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 7, 'Dios habló desde su santuario; y así me regocijaré, y repartiré a Siquem, y mediré el valle de los Tabernáculos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 8, 'Mío es Galaad, y mío es Manasés, y Efraín es la fortaleza principal mía. Judá es mi rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 9, 'Moab el vaso u objeto de mi esperanza, yo le conquistaré. Por Idumea extenderé mis plantas; se me harán amigos, se me someterán los extranjeros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 10, '¿Quién me guiará a la ciudad fuerte? ¿Quién me conducirá hasta la Idumea?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 11, '¿Quién sino tu, ¡oh mi Dios! que nos habías desamparado? ¿No vendrás tú, oh Dios mío, a la cabeza de nuestros ejércitos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 12, 'Danos tu socorro en la tribulación');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 107, 13, 'Con Dios haremos proezas, y él aniquilará a nuestros enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 1, 'Líbrame, ¡oh Señor!, del hombre malvado, líbrame del hombre perverso.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 2, 'Aquellos que maquinaban mil iniquidades en su interior, todo el día están armándome contiendas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 3, 'Se aguzaron sus lenguas viperinas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 4, 'Defiéndeme, Señor, de las manos del pecador; y líbrame de los hombres inicuos, que intentan dar conmigo en tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 5, 'Un lazo oculto me armaron los soberbios');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 6, 'Mas yo dije al Señor: Tú eres mi Dios, escucha, ¡oh Señor! mi humilde súplica.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 7, '¡Señor, Señor!, de cuya fortaleza depende mi salvación, tú pusiste a cubierto mi cabeza el día del combate.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 8, 'No me entregues, Señor, contra mi deseo en manos del pecador. Han maquinado los impíos contra mí; no me desampares tú, no sea que triunfen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 9, 'El resultado principal de sus artificios o enredos, toda la malignidad de sus labios vendrá a descargar contra ellos mismos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 10, 'Caerán sobre ellos ascuas, rayos del cielo o carbones encendidos; tú los precipitarás en el fuego, y perecerán abrumados por los desastres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 11, 'El hombre charlatán no perdurará en la tierra');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 12, 'Yo sé de cierto que el Señor tomará a su cargo la causa del desvalido y la venganza de los pobres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 139, 13, 'Y así los justos glorificarán eternamente tu santo Nombre, y los hombres rectos gozarán de la vista de tu divina presencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 1, 'Alcé mi voz para clamar al Señor');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 2, 'Derramo en su presencia mi oración, y le represento la extrema tribulación mía.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 3, 'Está ya para desfallecer mi espíritu; y tú, Señor, conoces bien mi recto proceder. En este camino, por donde yo andaba, me tendieron ocultos lazos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 4, 'Pensativo miraba si se ponía alguno a mi derecha para defenderme; peno nadie dio a entender que me conociese. Me hallé sin poder huir, y sin nadie que mirase por mi vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 5, 'Clamé a ti, oh Señor, diciendo: Tú eres la única esperanza mía, mi porción en la dichosa tierra de los vivientes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 6, 'Atiende a mi humilde súplica, porque me hallo sumamente abatido. Líbrame de los que me persiguen, porque son más fuertes que yo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 141, 7, 'Saca de esta cárcel a mi alma para que alabe tu santo Nombre');
